-- Drop foreign key constraints so any guide/article ID can be liked and bookmarked
alter table public.guide_likes drop constraint if exists guide_likes_guide_id_fkey;
alter table public.bookmarks drop constraint if exists bookmarks_guide_id_fkey;

-- Ensure all current articles exist in public.guides for joins
on conflict (id) do update set
  title = excluded.title,
  summary = excluded.summary,
  category = excluded.category,
  author_name = excluded.author_name;
